M={'u2-sycon': ['sycon_external', 'sycon_ls', 'sycon_spicules'], 'u3-fasciola': ['fasciola_external', 'fasciola_digestive', 'fasciola_excretory', 'fasciola_lifecycle'], 'u3-ascaris': ['ascaris_external', 'ascaris_digestive', 'ascaris_ts', 'ascaris_bodywall'], 'u4-annelida': ['earthworm_external', 'earthworm_digestive', 'earthworm_vascular', 'earthworm_nervous', 'earthworm_excretory', 'earthworm_reproductive'], 'u4-penaeus': ['penaeus_external', 'penaeus_appendages', 'penaeus_digestive', 'penaeus_respiratory', 'penaeus_circulatory', 'penaeus_nervous', 'penaeus_reproductive'], 'u5-pila': ['pila_external', 'pila_pallial', 'pila_digestive', 'pila_circulatory', 'pila_nervous', 'pila_reproductive'], 'u5-asterias': ['asterias_oral', 'asterias_aboral', 'asterias_digestive', 'asterias_nervous', 'asterias_reproductive'], 'u2-obelia': ['obelia_colony', 'obelia_hydranth_gonangium', 'obelia_medusa', 'obelia_lifecycle'], 'u4-nereis': ['nereis_external', 'nereis_parapodium', 'nereis_digestive', 'nereis_circulatory', 'nereis_nervous']}

PDFREF={
'sycon':'p13–14','fasciola':'p22','ascaris':'p26','earthworm':'p31','penaeus':'p35','pila':'p42','asterias':'p45–46','obelia':'p17','nereis':'p30'}

TRUSTED_LOCAL_CSP = "img-src 'self' data: blob: https://appassets.androidplatform.net;"
SVG_NAMESPACE = 'http://www.w3.org/2000/svg'

def assert_offline_safety(payload):
 # The Android WebViewAssetLoader origin is a local in-app origin, not a remote
 # dependency.  Permit it only in the single accepted CSP img-src directive.
 if payload.count(TRUSTED_LOCAL_CSP) != 1:
  raise SystemExit('trusted local appassets CSP occurrence mismatch')
 scrub=payload.replace(SVG_NAMESPACE,'').replace(TRUSTED_LOCAL_CSP,'')
 forbidden=['<iframe','eval(','new Function(','http://','https://']
 for token in forbidden:
  if token in scrub: raise SystemExit('forbidden token after batch2: '+token)

def main(root):
 root=Path(root).resolve(); targets=[root/'academic_payload/index.html',root/'app/src/main/assets/www/index.html']
 injection='<script id="v188-pencil-batch2">\n'+ '\n'.join("window.ORG_SYSTEM_DIAGRAMS[%s]=(window.ORG_SYSTEM_DIAGRAMS[%s]||'')+%s;"%(json.dumps(lesson),json.dumps(lesson),json.dumps(''.join(P[k] for k in keys),ensure_ascii=False)) for lesson,keys in M.items())+'\n</script>\n'
 for p in targets:
  s=p.read_text(encoding='utf-8')
  if 'id="v188-pencil-batch2"' in s: raise SystemExit('batch2 already applied')
  anchor='<script id="v188-contextual-atlas">'
  if anchor not in s or 'id="v188-pencil-batch1"' not in s: raise SystemExit('apply v188 + batch1 first')
  s=s.replace(anchor,injection+anchor,1); p.write_text(s,encoding='utf-8',newline='\n')
 if targets[0].read_bytes()!=targets[1].read_bytes(): raise SystemExit('payload copies diverged')
 payload=targets[0].read_text(encoding='utf-8')
 assert_offline_safety(payload)
 rows=[]
 def add(org,lesson,key,fig,pdf,status='PASS',notes='Source/static audit only; physical-device QA not performed.'):
  tamil='PASS' if 'lang="ta"' in fig and 'ta-explain' in fig else 'PENDING'
  rows.append([org,lesson,key.replace('_',' '),pdf,'batch2#'+key,lesson+' ORG_SYSTEM_DIAGRAMS','YES',status,status,'PASS',tamil,'PASS-static','PASS-source viewer',status,notes])
 orgnames={'sycon':'Sycon','fasciola':'Fasciola hepatica','ascaris':'Ascaris lumbricoides','earthworm':'Earthworm','penaeus':'Penaeus','pila':'Pila globosa','asterias':'Asterias','obelia':'Obelia','nereis':'Nereis'}
 for lesson,keys in M.items():
  prefix=keys[0].split('_')[0]
  for key in keys: add(orgnames[prefix],lesson,key,P[key],PDFREF[prefix])
 b1=[
 ['Sycon','u2-sycon','Canal system + water flow','p13–14','batch1#SYCON','u2-sycon ORG_SYSTEM_DIAGRAMS','YES','PASS','PASS','PASS','PASS','PASS-static','PASS-source viewer','PASS','Water pathway explicitly audited.'],
 ['Fasciola hepatica','u3-fasciola','Reproductive system','p22','batch1#FASCIOLA','u3-fasciola ORG_SYSTEM_DIAGRAMS','YES','PASS','PASS','PASS','PASS','PASS-static','PASS-source viewer','PASS','High-risk topology retained for later device QA.'],
 ['Ascaris lumbricoides','u3-ascaris','Male/female reproductive systems','p26','batch1#ASCARIS','u3-ascaris ORG_SYSTEM_DIAGRAMS','YES','PASS','PASS','PASS','PASS','PASS-static','PASS-source viewer','PASS','Male/female systems remain visually separated.'],
 ['Earthworm','u4-annelida','Combined digestive/vascular/nervous/excretory plate','p31','batch1#EARTHWORM','u4-annelida ORG_SYSTEM_DIAGRAMS','YES','PASS','PASS','PASS','PASS','FAIL-congestion','PENDING','FAIL','Composite retained only as overview; not accepted as primary teaching plate. Six system-specific Batch-2 plates added.'],
 ['Penaeus','u4-penaeus','Appendages/gills/internal anatomy overview','p35','batch1#PENAEUS','u4-penaeus ORG_SYSTEM_DIAGRAMS','YES','PENDING','PENDING','PASS','PASS','PENDING','PENDING','PENDING','Overview retained, but appendage identity must be judged from dedicated Batch-2 plate and later device QA.'],
 ['Pila globosa','u5-pila','Respiratory/principal systems overview','p42','batch1#PILA','u5-pila ORG_SYSTEM_DIAGRAMS','YES','PASS','PASS','PASS','PASS','PENDING','PENDING','PENDING','Overview supplemented by system-specific plates.'],
 ['Asterias','u5-asterias','WVS + ampulla/tube foot','p45–46','batch1#ASTERIAS','u5-asterias ORG_SYSTEM_DIAGRAMS','YES','PASS','PASS','PASS','PASS','PASS-static','PASS-source viewer','PASS','High-risk WVS plate retained.'] ]
 rows=b1+rows
 out=root/'provenance/V188_SVG_AUDIT_MANIFEST.csv'
 with out.open('w',encoding='utf-8',newline='') as f:
  w=csv.writer(f); w.writerow(['Organism','Lesson ID','Figure/System','PDF Reference','SVG Identifier/File','Embedded Location','Embedded','Biological Audit','Leader-Line Audit','English Labels','Tamil Labels','360px Audit','Enlarged-View Source Audit','Status','Notes']); w.writerows(rows)
 from collections import defaultdict
 d=defaultdict(lambda:[0,0,0,0,0])
 for r in rows:
  a=d[r[0]]; a[0]+=1; a[1]+=1 if r[4] else 0; a[2]+=1 if r[6]=='YES' else 0; a[3]+=1 if r[13]=='PASS' else 0; a[4]+=1 if r[13] != 'PASS' else 0
 cm=root/'provenance/V188_SVG_COMPLETENESS_MATRIX.csv'
 with cm.open('w',encoding='utf-8',newline='') as f:
  w=csv.writer(f); w.writerow(['Organism','Required figures','Created','Embedded','Passed','Pending/Failed']); [w.writerow([k]+v) for k,v in sorted(d.items())]
 print('V188_BATCH2_NEW_PLATES='+str(len(P))); print('V188_MANIFEST_ROWS='+str(len(rows))); print('V188_PASS_ROWS='+str(sum(r[13]=='PASS' for r in rows))); print('V188_NONPASS_ROWS='+str(sum(r[13]!='PASS' for r in rows))); print('V188_BUILD_ELIGIBLE=NO')

if __name__=='__main__': main(sys.argv[1])
